Now checking the second Codex plugin variant, QwenWork locally, and how the computer surface is toggled:

[tool-call run_code] {"code": "
const t = (x: any) => x.kind === "foreground" ? (x.stdout.text + (x.stderr.text || "")) : JSON.stringify(x);
const [cuVariant, qwen, ws] = await Promise.all([
 tools.pwsh({ command: `$p='C:\\Users\\jjq21\\.codex\\plugins\\cache\\openai-bundled'
Get-ChildItem $p -Directory | Select-Object Name | Format-Table -AutoSize | Out-String -Width 150
foreach ($d in 'computer-use','unified-computer-use') {
 echo "=== $d ==="
 Get-ChildItem -Recurse -Force "$p\\$d" -ErrorAction SilentlyContinue | Select-Object FullName | Format-Table -AutoSize | Out-String -Width 250
 $m = Get-ChildItem -Recurse -Force "$p\\$d" -Filter '.mcp.json' -ErrorAction SilentlyContinue | Select-Object -First 1
 if ($m) { echo '--- CUA surfaces ---'; Select-String -Path $m.FullName -Pattern 'CUA_REPL_ENABLED_SURFACES' | ForEach-Object { $_.Line.Trim() } }
}`, description: "Compare both computer-use plugin variants" }),
 tools.pwsh({ command: `echo '=== qwenwork dirs ==='; Get-ChildItem 'C:\\Users\\jjq21' -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'qwen' } | Select-Object FullName | Format-Table -AutoSize | Out-String -Width 200
echo '=== Programs ==='; Get-ChildItem 'C:\\Users\\jjq21\\AppData\\Local\\Programs' -Directory -ErrorAction SilentlyContinue | Select-Object Name | Format-Table -AutoSize -Out-String -Width 150
echo '=== 千问/Qwen processes ==='; Get-Process | Where-Object { $_.ProcessName -match 'qwen|Qoder|tongyi|千问' } | Select-Object ProcessName,Id | Format-Table -AutoSize | Out-String -Width 150`, description: "Check QwenWork installation on machine" }),
 tools.web_search({ queries: ["CUA_REPL_ENABLED_SURFACES computer 启用 Codex 电脑操作", "Codex 电脑操作 Windows 怎么开启 computer use 教程"] }),
]);
console.log("### plugin variants\n" + t(cuVariant).slice(0, 2600));
console.log("\n### qwen local\n" + t(qwen).slice(0, 1500));
console.log("\n### search\n" + (ws.content ?? "(none)"));
console.log(ws.sources.slice(0,8).map(s=>`- [${s.title}](${s.url})`).join("\n"));
", "description": "Compare plugin variants and check QwenWork presence"}

